528	class DraggingUtils {
529		constructor( { page } ) {
530			this.page = page;
531	
532			this.dropZone = page.locator( 'data-testid=block-popover-drop-zone' );
533			this.insertionIndicator = page.locator(
534				'data-testid=block-list-insertion-point-indicator'
535			);
536		}
537	
538		async dragOver( x, y ) {
539			// Call the move function twice to make sure the `dragOver` event is sent.
540			// @see https://github.com/microsoft/playwright/issues/17153
541			for ( let i = 0; i < 2; i += 1 ) {
542				await this.page.mouse.move( x, y );
543			}
544		}
545	
546		async simulateDraggingHTML( html ) {
547			// Insert a dummy draggable element on the page to simulate dragging
548			// HTML from other places. The dummy element will get removed once the drag starts.
549			await this.page.evaluate( ( _html ) => {
550				const draggable = document.createElement( 'div' );
551				draggable.draggable = true;
552				draggable.style.width = '10px';
553				draggable.style.height = '10px';
554				// Position it at the top left corner for convenience.
555				draggable.style.position = 'fixed';
556				draggable.style.top = 0;
557				draggable.style.left = 0;
558				draggable.style.zIndex = 999999;
559	
560				draggable.addEventListener(
561					'dragstart',
562					( event ) => {
563						// Set the data transfer to some HTML on dragstart.
564						event.dataTransfer.setData( 'text/html', _html );
565	
566						// Some browsers will cancel the drag if the source is immediately removed.
567						setTimeout( () => {
568							draggable.remove();
569						}, 0 );
570					},
571					{ once: true }
572				);
573	
574				document.body.appendChild( draggable );
575			}, html );
576	
577			// This is where the dummy draggable element is at.
578			await this.page.mouse.move( 0, 0 );
579			await this.page.mouse.down();
580		}
581	
582		async confirmValidDropZonePosition( element ) {
583			// Check that both x and y axis of the dropzone
584			// have a less than 1 difference with a given target element
585			const box = await this.dropZone.boundingBox();
586			if ( ! box ) {
587				return false;
588			}
589	
590			return (
591				Math.abs( element.x - box.x ) < 1 &&
592				Math.abs( element.y - box.y ) < 1
593			);
594		}
595	}
